style.css:
/* Pinterest buttons — hot pink ? */
[data-test-id="pin-save-button"],
[data-test-id="pin-save-button"] button,
button[aria-label*="Save"] {
    background-color: #FF69B4 !important;
    border-color: #FF69B4 !important;
    color: white !important;
}

/* Keep them pink when hovering */
[data-test-id="pin-save-button"]:hover,
[data-test-id="pin-save-button"] button:hover,
button[aria-label*="Save"]:hover {
    background-color: #FF69B4 !important;
    border-color: #FF69B4 !important;
    color: white !important;
}
